        // If ball at 1 -> moves to 2.
        // If ball at 2 -> moves to 1.

        // Let's create a function to apply one move to a position.
        // move(pos, moveNumber):
        //   if moveNumber is odd: swap 0 and 1.
        //     if pos == 0 return 1
        //     if pos == 1 return 0
        //     if pos == 2 return 2
        //   if moveNumber is even: swap 1 and 2.
        //     if pos == 0 return 0
        //     if pos == 1 return 2
        //     if pos == 2 return 1

