        // We'll store the state as a tuple (pos0, pos1, pos2) where pos_i is the current position of the ball that started at i.

        let states = [[0, 1, 2]]; // initial state: ball starting at 0 is at 0, etc.
        let seen = new Map();
        seen.set("0,1,2", 0);

        let cycleStart = -1;
        let cycleLen = -1;

        // We'll simulate until we find a repeat.
        // Max steps needed is small (at most 3! = 6 for permutations, but this is a specific sequence).

        for (let step = 1; step <= 100; step++) {
            let prev = states[states.length - 1];
            let next = [
                applyMove(prev[0], step),
                applyMove(prev[1], step),
                applyMove(prev[2], step)
            ];
            states.push(next);
            let key = next.join(',');
            if (seen.has(key)) {
                cycleStart = seen.get(key);
                cycleLen = step - cycleStart;
                break;
