            seen.set(key, step);
        }

        // Now we have the cycle.
        // The state at step n is determined by:
        // If n < cycleStart, use states[n].
        // Else, use states[cycleStart + (n - cycleStart) % cycleLen].

        let effectiveStep;
        if (n < cycleStart) {
            effectiveStep = n;
        } else {
            effectiveStep = cycleStart + (n - cycleStart) % cycleLen;
        }

        // states[effectiveStep] is an array [p0, p1, p2] where p_i is the final position of the ball that started at i.
        // We want the initial position i such that p_i == x.
        let finalState = states[effectiveStep];
        let initialPos = -1;
        for (let i = 0; i < 3; i++) {
            if (finalState[i] === x) {
                initialPos = i;
                break;
            }
        }

